import{_ as e,o,c as n,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2024-08-21","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2024-08-21","date":"2024-08-21T00:00:00.000Z","updated":"2024-09-04T00:00:00.000Z","tags":["Ceph","分布式存储","RGW","重构","会议纪要"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-08-21.md","filePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-08-21.md","lastUpdated":1780460162000}'),s={name:"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-08-21.md"};function g(p,t,i,l,a,_){return o(),n("div",null,[...t[0]||(t[0]=[r("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2024年8月21日</p><p><strong>参会人员</strong>： [请列出参会人员姓名]</p><p><strong>会议主题</strong>： Ceph 分布式存储 RGW 组件重构进展及议题讨论</p><p><strong>一、议题一：Ceph 追踪功能进展</strong></p><ul><li><strong>当前追踪功能</strong>： 包括 Squid 前端请求追踪、RGW 追踪、OSD 追踪、Jager 排序通过 SEF ADM、多部分上传追踪、端到端追踪、条件追踪（使用 Lua 脚本）等。</li><li><strong>正在进行中的工作</strong>： 块和清理（Adam 负责），存储桶索引追踪。</li><li><strong>未来工作计划</strong>： 扩展端到端追踪至所有操作，完成存储桶索引日志追踪，添加其他多站点追踪点，优化追踪命名规范，通过 Rook 添加编排，实现其他端到端追踪（如 RBD 和 SEFS），考虑迁移至 OpenTelemetry 协议。</li><li><strong>非开发相关</strong>： 推广追踪功能，教育团队，创建代码演示和文档，制定追踪策略。</li></ul><p><strong>二、议题二：用户账户迁移</strong></p><ul><li><strong>当前迁移方案</strong>： 用户需要移除所有订阅和主题，系统管理员迁移用户至账户，用户重新创建主题并重新订阅。</li><li><strong>问题</strong>： 迁移过程中用户无法接收通知，需要大量人工操作。</li><li><strong>改进方案</strong>： 用户继续使用现有通知订阅，系统管理员将用户迁移至账户，用户创建新的主题，用户将桶重新订阅到新主题，当旧主题不再使用时，管理员可以使用命令删除旧主题。</li><li><strong>后续工作</strong>： 更新官方文档，编写测试用例。</li></ul><p><strong>三、其他议题</strong></p><ul><li>[请列出其他议题及讨论内容]</li></ul><p><strong>四、行动计划</strong></p><ul><li>[请列出各议题的行动计划及负责人]</li></ul><p><strong>五、会议总结</strong></p><p>本次会议讨论了 Ceph 分布式存储 RGW 组件的重构进展，并对追踪功能和用户账户迁移等关键议题进行了深入讨论和决策。会议明确了下一步的工作计划和行动计划，为项目的顺利推进奠定了基础。</p>",14)])])}const R=e(s,[["render",g]]);export{d as __pageData,R as default};
